// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the caller 'from' and the value v and the single recipient addr
    function testFuzz_property(address from, address recip, uint256 v) public {
        // keep recip non-zero (admissible) and ensure we pass a single-element array
        vm.assume(recip != address(0));

        address[] memory tos = new address[](1);
        tos[0] = recip;

        // Deploy a helper that implements transferFrom and will succeed, but will revert on transfer selector
        CalleeImplementsTransferFrom helper = new CalleeImplementsTransferFrom();

        bool ok;
        // call through c.transfer and observe whether it reverts or not
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always returns true (does not revert) because it calls transferFrom selector
        // on the callee which is implemented to succeed; the mutant that changes selector to transfer(...) will hit
        // a function that reverts on that selector, causing ok == false for some fuzzed inputs (callee address)
        assertTrue(ok);
    }
}

// Helper: implements transferFrom(address,address,uint256) and succeeds; but does NOT implement transfer(address,address,uint256)
// so calls with the transfer selector will hit fallback which reverts. This differentiates the correct selector vs the mutant.
contract CalleeImplementsTransferFrom {
    // explicit function matching the reference's selector
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        // Record nothing; just return true to indicate success
        return true;
    }

    // fallback reverts to simulate the callee not supporting the alternate selector
    fallback() external payable {
        revert("unsupported selector");
    }

    receive() external payable {
        // accept plain transfers
    }
}
